#!/usr/bin/env python3
"""Tests for fetch_rusty_v8.py, the step that hands the `v8` crate's build
script a prebuilt V8 from the Brainwires rusty_v8 release: the manifest is
parsed strictly, the release tag must match Cargo.lock's `v8` version, both
files are verified against their pinned SHA-256, and every failure is fatal
(fail closed) and leaves no unverified file behind. The last cases check the
repository's own manifest against its Cargo.lock.

Usage: python3 -I .github/denext-runtime/fetch_rusty_v8_test.py
"""

import hashlib
import importlib.util
import os
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
SCRIPT = os.path.join(HERE, "fetch_rusty_v8.py")

spec = importlib.util.spec_from_file_location("fetch_rusty_v8", SCRIPT)
fr = importlib.util.module_from_spec(spec)
spec.loader.exec_module(fr)

TARGET = "x86_64-unknown-linux-gnu"
LIB = b"static library bytes"
BINDING = b"// bindgen output\n"
LOCK = """# This file is automatically @generated by Cargo.

[[package]]
name = "v8"
version = "152.2.1+denext.1"
source = "git+https://github.com/Brainwires/rusty_v8?rev=abc#abc"
"""


def sha(data):
  return hashlib.sha256(data).hexdigest()


def manifest(lib=LIB, binding=BINDING, tag="v152.2.1-denext.1", extra=""):
  return (
    "# a comment\n"
    "# repo: Brainwires/rusty_v8\n"
    f"# tag: {tag}\n"
    f"{sha(lib)}  librusty_v8_release_{TARGET}.a.gz\n"
    f"{sha(binding)}  src_binding_release_{TARGET}.rs\n" + extra
  )


class FakeRelease:
  """A fetcher serving `files` by name, recording the URLs asked for."""

  def __init__(self, files):
    self.files = files
    self.urls = []

  def __call__(self, url, dest):
    self.urls.append(url)
    with open(dest, "wb") as f:
      f.write(self.files[url.rsplit("/", 1)[1]])


def release():
  return FakeRelease({
    f"librusty_v8_release_{TARGET}.a.gz": LIB,
    f"src_binding_release_{TARGET}.rs": BINDING,
  })


class Manifest(unittest.TestCase):
  def test_parses_headers_and_entries(self):
    m = fr.parse_manifest(manifest())
    self.assertEqual(m["repo"], "Brainwires/rusty_v8")
    self.assertEqual(m["tag"], "v152.2.1-denext.1")
    self.assertEqual(m["files"][f"src_binding_release_{TARGET}.rs"], sha(BINDING))

  def test_a_malformed_line_is_refused(self):
    with self.assertRaisesRegex(fr.Failure, "not `<sha256>  <file>`"):
      fr.parse_manifest(manifest(extra="deadbeef  short.rs\n"))

  def test_a_duplicate_entry_is_refused(self):
    with self.assertRaisesRegex(fr.Failure, "listed twice"):
      fr.parse_manifest(manifest(extra=f"{sha(LIB)}  src_binding_release_{TARGET}.rs\n"))

  def test_repo_and_tag_are_required(self):
    with self.assertRaisesRegex(fr.Failure, "needs `# repo:`"):
      fr.parse_manifest(f"{sha(LIB)}  a.gz\n")

  def test_windows_names_the_lib_archive(self):
    self.assertEqual(
      fr.artifact_names("aarch64-pc-windows-msvc"),
      (
        "rusty_v8_release_aarch64-pc-windows-msvc.lib.gz",
        "src_binding_release_aarch64-pc-windows-msvc.rs",
      ),
    )


class Tag(unittest.TestCase):
  def test_tag_matches_the_lock_version(self):
    fr.check_tag("v152.2.1-denext.1", fr.lock_v8_version(LOCK))

  def test_a_tag_for_another_version_is_refused(self):
    with self.assertRaisesRegex(fr.Failure, "expected tag v152.2.1-denext.1"):
      fr.check_tag("v152.2.1-denext.2", "152.2.1+denext.1")

  def test_a_crates_io_version_has_no_release(self):
    with self.assertRaisesRegex(fr.Failure, "Cargo.lock's v8 is 152.2.0"):
      fr.check_tag("v152.2.1-denext.1", "152.2.0")


class Fetch(unittest.TestCase):
  def setUp(self):
    self.tmp = tempfile.TemporaryDirectory()
    self.dest = os.path.join(self.tmp.name, "out")
    os.environ.pop("RUSTY_V8_MIRROR", None)

  def tearDown(self):
    self.tmp.cleanup()

  def run_fetch(self, text=None, fetcher=None, **kwargs):
    return fr.fetch(
      TARGET, self.dest, manifest_text=text or manifest(), lock_text=LOCK,
      fetcher=fetcher or release(), **kwargs,
    )

  def test_downloads_verifies_and_returns_the_build_env(self):
    fetcher = release()
    env = self.run_fetch(fetcher=fetcher)
    self.assertEqual(
      fetcher.urls[0],
      "https://github.com/Brainwires/rusty_v8/releases/download/"
      f"v152.2.1-denext.1/librusty_v8_release_{TARGET}.a.gz",
    )
    self.assertEqual(env["RUSTY_V8_ARCHIVE_SHA256"], sha(LIB))
    with open(env["RUSTY_V8_ARCHIVE"], "rb") as f:
      self.assertEqual(f.read(), LIB)
    with open(env["RUSTY_V8_SRC_BINDING_PATH"], "rb") as f:
      self.assertEqual(f.read(), BINDING)

  def test_a_changed_binding_is_refused_and_removed(self):
    with self.assertRaisesRegex(fr.Failure, "src_binding_release_.*SHA-256"):
      self.run_fetch(text=manifest(binding=b"something else"))
    self.assertFalse(
      os.path.exists(os.path.join(self.dest, f"src_binding_release_{TARGET}.rs"))
    )

  def test_a_changed_library_is_refused(self):
    with self.assertRaisesRegex(fr.Failure, "librusty_v8_release_.*SHA-256"):
      self.run_fetch(text=manifest(lib=b"tampered"))

  def test_an_unlisted_target_is_refused(self):
    with self.assertRaisesRegex(fr.Failure, "lists no librusty_v8_release_riscv"):
      fr.fetch(
        "riscv64gc-unknown-linux-gnu", self.dest, manifest_text=manifest(),
        lock_text=LOCK, fetcher=release(),
      )

  def test_a_mirror_in_the_environment_is_refused(self):
    os.environ["RUSTY_V8_MIRROR"] = "https://example.invalid"
    try:
      with self.assertRaisesRegex(fr.Failure, "RUSTY_V8_MIRROR is set"):
        self.run_fetch()
    finally:
      del os.environ["RUSTY_V8_MIRROR"]

  def test_local_files_are_verified_too(self):
    src = os.path.join(self.tmp.name, "src")
    os.makedirs(src)
    for name, data in release().files.items():
      with open(os.path.join(src, name), "wb") as f:
        f.write(data)
    env = self.run_fetch(source_dir=src, fetcher=lambda url, dest: self.fail(url))
    self.assertEqual(env["RUSTY_V8_ARCHIVE_SHA256"], sha(LIB))
    with open(os.path.join(src, f"librusty_v8_release_{TARGET}.a.gz"), "wb") as f:
      f.write(b"edited")
    with self.assertRaisesRegex(fr.Failure, "SHA-256"):
      self.run_fetch(source_dir=src)


class Repository(unittest.TestCase):
  """The checked-in manifest: one pinned pair per release target, for the
  release Cargo.lock's `v8` names."""

  TARGETS = [
    "x86_64-unknown-linux-gnu",
    "aarch64-unknown-linux-gnu",
    "x86_64-apple-darwin",
    "aarch64-apple-darwin",
    "x86_64-pc-windows-msvc",
    "aarch64-pc-windows-msvc",
  ]

  def test_every_release_target_is_pinned(self):
    with open(fr.MANIFEST, encoding="utf-8") as f:
      m = fr.parse_manifest(f.read())
    for target in self.TARGETS:
      for name in fr.artifact_names(target):
        self.assertIn(name, m["files"], target)
    self.assertEqual(len(m["files"]), 2 * len(self.TARGETS))

  def test_the_manifest_tag_matches_cargo_lock(self):
    with open(fr.MANIFEST, encoding="utf-8") as f:
      m = fr.parse_manifest(f.read())
    with open(fr.LOCKFILE, encoding="utf-8") as f:
      fr.check_tag(m["tag"], fr.lock_v8_version(f.read()))


if __name__ == "__main__":
  unittest.main()
